<?php
return [
    'up' => function (PDO $db): void {
        $id = match ($db->getAttribute(PDO::ATTR_DRIVER_NAME)) {
            'mysql' => 'INT AUTO_INCREMENT PRIMARY KEY',
            'pgsql' => 'INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY',
            'sqlite' => 'INTEGER PRIMARY KEY AUTOINCREMENT',
        };
        $db->exec("CREATE TABLE contacts (
            id {$id}, name VARCHAR(100) NOT NULL, email VARCHAR(254) NOT NULL,
            phone VARCHAR(30) NOT NULL DEFAULT '', interest VARCHAR(50) NOT NULL,
            message TEXT NOT NULL, is_read BOOLEAN NOT NULL DEFAULT FALSE,
            created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
        )");
    },
    'down' => function (PDO $db): void { $db->exec('DROP TABLE contacts'); },
];
